from collections import defaultdict, deque


def word_ladder(begin_word, end_word, word_list):
    words = set(word_list)
    if end_word not in words:
        return 0

    # Group the words by "pattern": the word with one letter replaced by a star ("c*ld", "co*d", ...).
    # Words in the same group differ in exactly that one position, so they are neighbors.
    groups = defaultdict(list)
    for word in words | {begin_word}:
        for i in range(len(word)):
            groups[word[:i] + "*" + word[i + 1:]].append(word)

    queue = deque([(begin_word, 1)])
    seen = {begin_word}
    while queue:
        word, length = queue.popleft()
        for i in range(len(word)):
            for neighbor in groups[word[:i] + "*" + word[i + 1:]]:
                if neighbor == end_word:
                    return length + 1
                if neighbor not in seen:
                    seen.add(neighbor)
                    queue.append((neighbor, length + 1))
    return 0
